int op_a(void) {
    mkdir("/app/inkwell", 0755);

    /* Never produce an atlas when a dump refers to a vanished unit. */
    if (n_miss() != 0) return 1;

    char paths[ROW_MAX][PATH_MAX_X];
    Row rows[ROW_MAX];
    int path_count = walk_units("/app/unitpit", paths, ROW_MAX);
